create function pg_temp.assert_n(ok boolean)returns void language plpgsql as $$begin if ok is not true then raise exception 'notification_assertion';end if;end$$;
create function pg_temp.deny_n(q text,c text)returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=c then return;end if;raise;end;raise exception 'expected_notification_denial';end$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000002',true);
do $$declare w uuid:='82000000-0000-4000-8000-000000000001';i jsonb;r jsonb;id uuid;begin
 i:=jsonb_build_object('command_id',gen_random_uuid(),'expected_version',0);r:=public.notification_v1_refresh(w,i);perform pg_temp.assert_n(r->>'affected'='1'and r->>'version'='2'and r=public.notification_v1_refresh(w,i));
 perform pg_temp.deny_n(format('select public.notification_v1_refresh(%L,%L)',w,(i||'{"expected_version":1}'::jsonb)::text),'40001');
 perform pg_temp.assert_n(public.notification_v1_unread_count(w,'{}')->>'unread_count'='1');
 id:=(public.notification_v1_list(w,'{"limit":1}')->'items'->0->>'id')::uuid;
 perform pg_temp.assert_n(public.notification_v1_list(w,jsonb_build_object('limit',1,'after_id',id))->'items'='[]'::jsonb);
 perform public.notification_v1_mark_read(w,jsonb_build_object('command_id',gen_random_uuid(),'id',id,'expected_version',2));
 perform pg_temp.assert_n(public.notification_v1_unread_count(w,'{}')->>'unread_count'='0');
 r:=public.notification_v1_refresh(w,jsonb_build_object('command_id',gen_random_uuid(),'expected_version',3));perform pg_temp.assert_n(r->>'affected'='0');
 r:=public.notification_v1_mark_all_read(w,jsonb_build_object('command_id',gen_random_uuid(),'expected_version',4));perform pg_temp.assert_n(r->>'affected'='0'and r->>'has_more'='false');
 perform pg_temp.deny_n(format('select public.notification_v1_list(%L,%L)',w,'{"limit":101}'),'22023');
end$$;
select set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_n(public.notification_v1_list('82000000-0000-4000-8000-000000000001','{}')->'items'='[]'::jsonb);
reset role;
create function pg_temp.notification_audit_failure()returns trigger language plpgsql as $$begin raise exception 'notification_cutpoint';end$$;
